/* BYOH memstate harness for the github functional axis (batch 7).
 *
 * TARGET SIGNATURE:
 *   int stringmatchlen_fuzz_test(void)   -- redis src/util.c
 *
 * WHY BYOH (not auto-generated): the function takes ZERO parameters, so the
 * auto-generator's harness calls it with no argument construction at all -- the seed file
 * is read (MAIN_OPEN) but never consumed, so every input drives the EXACT SAME run. The
 * function's only external input channel is libc's global `rand()` generator state: its
 * body loops 10,000,000 times, each iteration drawing pattern/string lengths+bytes via
 * `rand()` and feeding them to `stringmatchlen()`. To "establish real preconditions" for a
 * function like this, the harness must PRIME that generator from the seed -- so, before the
 * one call, it does `srand((unsigned)vb_take(4))`. This is NOT the forbidden "harness uses
 * rand()/time() for its own entropy" pattern (the rule against unseeded, unreproducible
 * variability) -- the srand() ARGUMENT is itself entirely derived from vb_take() (i.e. from
 * argv[1]), so the whole run is a pure, reproducible function of the seed FILE, exactly like
 * every other harness's `vb_int()`/`vb_len()`-derived arguments; it is simply the only lever
 * available to vary the precondition of a function whose own signature has no parameters.
 * (`stringmatchlen_fuzz_test` calling `rand()` unseeded/deterministically is also exactly
 * the semantics the ORIGINAL fuzz-test author intended -- see its own docstring "Fuzz
 * stringmatchlen() trying to crash it with bad input".)
 *
 * DISCRIMINATOR: the real body accumulates `total_matches` over 10M random pattern/string
 * pairs -- even the fully-degenerate case (`patternLen==0 && stringLen==0`, probability
 * (1/32)^2 per draw since both lengths are `rand()%32`) alone contributes ~9700 trivial
 * matches in expectation, on top of further random character-class matches, so the return
 * value is essentially ALWAYS a large positive int, regardless of the `srand()` draw. The
 * `stub` mock replaces the body with a bare `return 0;` -- so the folded return value (large
 * nonzero vs. exactly 0) discriminates on effectively every seed.
 *
 * RUNTIME NOTE: the 10,000,000-iteration loop is fixed in the frozen function bytes (cannot
 * be shortened) and costs ~3-4.5s per single run (measured -O0 in the ddiv-oracle
 * container, with and without ASAN/UBSAN) -- `capture_baseline` runs 4 passes per seed
 * (1 ASAN + 3 clean), so ~13-18s of real compute per seed. The job supplies exactly 50
 * hand-crafted 8-byte seeds (distinct `srand()` draws) to hit the full quota within a bounded
 * (~15 minute) freeze, rather than the (much slower, and no more discriminating) default
 * 240-seed random generator.
 *
 * CROSS-FILE DEPENDENCY (2nd reason this needs a hand-written harness): ``func.c`` here is
 * the WHOLE ``src/util.c`` TU (not just our target function), so a full link (needed to get
 * a runnable executable, unlike the recompile-only axis's ``-c``) also drags in every OTHER
 * function util.c defines. Several of those (``string2d``/``d2string``/``getRandomBytes``/
 * ``getAbsolutePath``/``makePath`` -- none reachable from ``stringmatchlen_fuzz_test``, which
 * only calls ``stringmatchlen``/``stringmatchlen_impl``, both self-contained within func.c)
 * reference externals from sibling TUs this bundle doesn't vendor: ``fast_float_strtod``
 * (deps/fast_float), ``fpconv_dtoa`` (deps/fpconv), ``sha256_*`` (src/sha256.c), and several
 * ``sds*`` string functions (src/sds.c). Since none of those callers are ever reached from
 * `main` (which only calls the zero-arg target), minimal never-invoked stand-ins -- dead code
 * in practice, exactly like ``coreutils_file_name_concat.c``'s ``xalloc_die`` stand-in --
 * satisfy the linker without needing to vendor those sibling TUs (which would themselves pull
 * in further headers/deps). Signatures copied verbatim from the bundled fpconv_dtoa.h/
 * fast_float_strtod.h/sha256.h/sds.h (already `#include`d transitively by func.c/util.h), so
 * no "conflicting types" mismatch against the real prototypes.
 *
 * Structure = funcharness.PRELUDE + <dead-code link stand-ins, see above> + MAIN_OPEN +
 * <middle> + HARNESS_FOOTER (verbatim). Contract: the seed is already in the VB_CUR/VB_N byte
 * cursor (MAIN_OPEN read argv[1]); derive an srand() seed from it, call the (zero-arg) target
 * once, fold its return value into vb_digest, then vb_dump(argv[2]) & exit 0. */
/* auto-generated by ddiv.funcharness -- DO NOT EDIT */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "func.c"

/* ---- program-exit memstate capture (see ddiv/functional.py) -----------------
 * Run func0 on a SAFE seed, fold its return value + any output buffers into a global
 * digest, then dump the program's own writable globals -- [.data, .bss], the part of
 * "all memory at program exit" that is deterministic across two independently-linked
 * binaries -- to argv[2]. The oracle byte-compares this dump to the frozen baseline:
 * equal => INTACT, differ-without-crash => silent VANISH, sanitizer/abort => DEVIATED. */

extern char __data_start[], _edata[], __bss_start[], _end[];

#define VB_MAXLEN   16     /* array length bound (paired T* arr, int n) */
#define VB_STRLEN   24     /* string length bound */
#define VB_INTBOUND 1000   /* scalar int magnitude bound */
#define VB_ARRLEN   8      /* default folded prefix for a lone array/pointer param */
#define VB_ARRCAP   256    /* generous zeroed allocation for a lone array/pointer param --
                            * modest over-reads by the original land on deterministic zeros;
                            * a read past the cap traps on the ORIGINAL build and the case is
                            * dropped by the safety/determinism filter (never a wrong verdict). */

static const unsigned char *VB_CUR; static long VB_N, VB_I;
static unsigned long vb_take(int nb){ unsigned long v=0; int k;
  for(k=0;k<nb;k++){ v |= (unsigned long)(VB_I<VB_N?VB_CUR[VB_I]:0) << (8*k); VB_I++; } return v; }
static long vb_int(void){ long m=2L*VB_INTBOUND+1; return (long)(vb_take(4)%m) - VB_INTBOUND; }
static double vb_dbl(void){ long x=(long)(vb_take(4)% (2000001UL)) - 1000000L; return (double)x/1000.0; }
static int vb_len(int bound){ return (int)(vb_take(1) % (unsigned)(bound+1)); }

/* result digest -- a global (lives in .data), so it is part of the dumped memstate.
 * FNV-1a over the function's return value + output buffers. */
static uint64_t vb_digest = 1469598103934665603ULL;
static void vb_mix(const void *p, unsigned long n){
  const unsigned char *b=(const unsigned char*)p; unsigned long i;
  for(i=0;i<n;i++){ vb_digest ^= b[i]; vb_digest *= 1099511628211ULL; } }
/* quantise a double to fixed-point (~1e-6 tolerance) so a numerically-equal result that
 * differs in the low mantissa bits (FMA / instruction-selection) still compares equal. */
static void vb_mix_d(double x){ long q;
  if(isnan(x)) q = (long)0x7ff8000000000000LL;
  else if(isinf(x)) q = (x>0?1:-1)*0x7fffffffffffffffLL;
  else q = (long)llround(x*1e6);
  vb_mix(&q, sizeof q); }
static void vb_mix_s(const char *s){
  if(!s){ unsigned char z=0; vb_mix(&z,1); return; }
  unsigned char nz=1; vb_mix(&nz,1); vb_mix(s, (unsigned long)strlen(s)); }

/* dump the program's writable globals (the deterministic part of the exit memstate). */
static void vb_dump(const char *path){
  VB_CUR=0; VB_N=0; VB_I=0;                  /* zero bookkeeping (VB_CUR holds a heap ptr) */
  if(!path) return;
  FILE *out = fopen(path, "wb"); if(!out) return;
  fwrite(__data_start, 1, (size_t)((char*)_edata   - (char*)__data_start), out);
  fwrite(__bss_start,  1, (size_t)((char*)_end     - (char*)__bss_start),  out);
  fclose(out); }

/* ---- dead-code link stand-ins (see file-header CROSS-FILE DEPENDENCY comment) --------
 * `func.c` (the whole src/util.c) defines other functions that call these externals, but
 * NONE of those callers are reachable from `main` (which only invokes the zero-arg target
 * stringmatchlen_fuzz_test -> stringmatchlen -> stringmatchlen_impl, all self-contained).
 * Minimal, never-invoked, exact-signature stand-ins just satisfy the linker. */
int fpconv_dtoa(double fp, char dest[24]) { (void)fp; if (dest) dest[0] = '\0'; return 0; }
double fast_float_strtod(const char *in, char **out) { if (out) *out = (char *)in; return 0.0; }
void sha256_init(SHA256_CTX *ctx) { (void)ctx; }
void sha256_update(SHA256_CTX *ctx, const BYTE data[], size_t len) { (void)ctx; (void)data; (void)len; }
void sha256_final(SHA256_CTX *ctx, BYTE hash[]) { (void)ctx; if (hash) memset(hash, 0, SHA256_BLOCK_SIZE); }
sds sdsnew(const char *init) { (void)init; return NULL; }
sds sdsempty(void) { return NULL; }
void sdsfree(sds s) { (void)s; }
sds sdscat(sds s, const char *t) { (void)t; return s; }
sds sdscatsds(sds s, const sds t) { (void)t; return s; }
sds sdstrim(sds s, const char *cset) { (void)cset; return s; }
void sdsrange(sds s, ssize_t start, ssize_t end) { (void)s; (void)start; (void)end; }
sds sdscatfmt(sds s, char const *fmt, ...) { (void)fmt; return s; }

int main(int argc, char **argv){
  if(argc<2){ fprintf(stderr,"usage: %s <seed> [dump]\n", argv[0]); return 64; }
  FILE *fp=fopen(argv[1],"rb"); if(!fp){ perror("open"); return 64; }
  fseek(fp,0,SEEK_END); long fsz=ftell(fp); fseek(fp,0,SEEK_SET);
  unsigned char *buf=(unsigned char*)malloc(fsz>0?fsz:1);
  long nread=(long)fread(buf,1,fsz>0?fsz:0,fp); fclose(fp);
  VB_CUR=buf; VB_N=nread; VB_I=0;

  /* Prime the ONLY input channel this zero-arg function reads: libc's global rand() state.
   * The seed is entirely derived from vb_take() (i.e. from argv[1]), so the run stays a
   * pure, reproducible function of the seed file -- see file-header WHY BYOH comment. */
  unsigned int vb_seed = (unsigned int)vb_take(4);
  srand(vb_seed);

  long vb_ret = (long)(stringmatchlen_fuzz_test());
  vb_mix(&vb_ret, sizeof vb_ret);

  vb_dump(argc>2?argv[2]:NULL);
  return 0;
}
